import { Sparkles } from "lucide-react";
import type { ReactNode } from "react";
import { Badge } from "./Badge";
import { Button } from "./Button";
import { Card } from "./Card";

export const AI_LABEL = "Tóm tắt do AI tạo, cần kiểm tra lại với hồ sơ gốc";

export interface AiSummaryPanelProps {
  /** AI is off unless the unit enables it. */
  enabled: boolean;
  /** "template" = built from fields by fixed rules; "ai" = generated by a model. */
  kind?: "template" | "ai";
  summary?: ReactNode;
  sourceHref?: string;
  sourceLabel?: string;
  loading?: boolean;
  onGenerate?: () => void;
}

/** Summaries only: never diagnosis, recommendation or a decision. The warning label is not optional. */
export function AiSummaryPanel({ enabled, kind = "ai", summary, sourceHref, sourceLabel = "Xem hồ sơ gốc", loading, onGenerate }: AiSummaryPanelProps) {
  return (
    <Card title="Tóm tắt hồ sơ" actions={<Badge tone={kind === "ai" ? "brand" : "neutral"} icon={<Sparkles aria-hidden className="size-3" />}>{kind === "ai" ? "AI" : "Theo mẫu"}</Badge>}>
      {!enabled ? (
        <p className="text-sm text-muted">Tóm tắt AI đang tắt tại đơn vị này. Quản trị viên có thể bật trong phần cài đặt.</p>
      ) : (
        <div className="space-y-3">
          {summary ? <div className="text-ink">{summary}</div> : <p className="text-sm text-muted">Chưa có bản tóm tắt.</p>}
          {kind === "ai" && summary && <p className="text-sm font-medium text-warn">{AI_LABEL}</p>}
          <div className="flex flex-wrap items-center gap-3">
            {onGenerate && <Button variant="secondary" loading={loading} onClick={onGenerate}>{summary ? "Tạo lại bản tóm tắt" : "Tạo bản tóm tắt"}</Button>}
            {sourceHref && <a className="text-sm font-medium text-brand underline underline-offset-2" href={sourceHref}>{sourceLabel}</a>}
          </div>
        </div>
      )}
    </Card>
  );
}
